#ifndef CA_GAME_OVER_H
#define CA_GAME_OVER_H

// The Catalan game over title (LANG_CA=1), included by src/menus/game_over.c after its other
// headers. "GAME OVER" is one graphic for every language: its tiles are the end of
// sGameOverTextAndBackgroundGfx, placed by sGameOverTextTileTable on a background of their own.
// In the German slot, GameOverInit then loads the Catalan title, "FI DE LA / PARTIDA", over
// both (ca/game_over_title.inc, generated by tools/gengameover.py from
// screens/game_over_title.png); the other languages load nothing more and keep the vanilla one.
// CA_SELFTEST builds load nothing either, so the self-test stays byte-identical to vanilla.

#ifdef CA_SELFTEST

#define CA_GAME_OVER_LOAD_TITLE()

#else // !CA_SELFTEST

#include "gba.h"
#include "types.h"
#include "syscalls.h"
#include "constants/game_state.h"
#include "structs/game_state.h"

extern const u32 sCaGameOverTitleGfx[];
extern const u32 sCaGameOverTitleTileTable[];

// The title's first tile: the vanilla title's, tile 640 of the graphics at VRAM 0x4000. The
// Catalan one may go on over the 64 free tiles up to the prompt's, at 0xA800 (192 in all,
// checked by tools/gengameover.py). The tilemap is the one sGameOverTextTileTable was loaded to.
#define CA_GAME_OVER_TITLE_GFX_VRAM (VRAM_BASE + 0x4000 + 640 * 32)
#define CA_GAME_OVER_TITLE_TILE_TABLE_VRAM (VRAM_BASE + 0x800)

#define CA_GAME_OVER_LOAD_TITLE() do {                                              \
    if (gLanguage == LANGUAGE_GERMAN)                                               \
    {                                                                               \
        LZ77UncompVram(sCaGameOverTitleGfx, CA_GAME_OVER_TITLE_GFX_VRAM);           \
        LZ77UncompVram(sCaGameOverTitleTileTable, CA_GAME_OVER_TITLE_TILE_TABLE_VRAM); \
    }                                                                               \
} while (0)

#endif // CA_SELFTEST

#endif // CA_GAME_OVER_H
